css:
/* ==== INTERFACE ====
reference: style:19-hand-drawn
方向：手绘手账感结合科学曲线，采用深墨蓝手绘轮廓线、圆润微倾与不规则角、轻量水洗墨迹质感；用户指定配色采用蓝色与青色为主调，底色选用清爽透气微泛蓝青的草稿纸底 (#f3f8fa)，文字使用墨水深蓝 (#162b3d)，强调面积使用纯净钴蓝 (#1d63d8) 与明朗手绘青 (#0ea5a8)。
token --bg: 页面底色 (#f3f8fa)。
token --text: 深墨蓝主文字色 (#162b3d)。
token --muted: 笔触中性注记色 (#5a7184)。
token --primary-blue: 手绘强调主蓝 (#1d63d8)。
token --accent-cyan: 手绘强调青色 (#0ea5a8)。
token --paper-border: 手绘墨水线边框色 (#20394f)。
token --font-sans: 正文与交互字体 (Inter + LXGW WenKai)。
token --font-display: 手写标题与强调字体 (Caveat + LXGW WenKai)。
class .nt-title: 页面主标题，默认 44px/1.2，英文字优先 Caveat (600)，中文字承接 LXGW WenKai (500)。
class .nt-subtitle: 副标题与小节名，24px/1.35，文楷搭配深墨蓝。
class .nt-lead: 引导说明文字，20px/1.5。
class .nt-body: 正文段落，17px/1.6。
class .nt-label: 刻度标签与交互说明，14px/1.4，Inter 搭配文楷。
class .nt-hand-box: 带有手绘不规律圆角、微扭曲描边与微偏移浅蓝墨水硬阴影的容器。
class .nt-hand-btn: 手绘轮廓交互按钮，带有点击下沉与描边位移反馈。
class .nt-slider: 手绘感滑块控件，青蓝手捏旋钮与圆头导轨。
class .nt-chart: 图表共享容器，内含 SVG 手绘圆头曲线 (.nt-curve)、关键数据强调点 (.nt-node)、虚线参考标尺 (.nt-grid-line)。
SVG / 图表用法示例：
<svg class="nt-chart" viewBox="0 0 800 450">
  <path class="nt-grid-line" d="M50 400 L750 400" />
  <path class="nt-curve nt-curve-blue" d="..." />
  <circle class="nt-node nt-node-cyan" cx="600" cy="120" r="7" />
  <text class="nt-chart-text" x="615" y="125">Yr 5: ¥248.83</text>
</svg>
默认：舞台无外部图片依赖，内置轻微手工方格草稿网格点阵底纹。
==== /INTERFACE ==== */

@font-face {
  font-family: "NTF-caveat";
  src: url("fonts/library/caveat/face-0.ttf");
  font-weight: 400 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-lxgw-wenkai";
  src: url("fonts/library/lxgw-wenkai/face-0.ttf");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-lxgw-wenkai";
  src: url("fonts/library/lxgw-wenkai/face-1.ttf");
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

:root {
  --bg: #f3f8fa;
  --bg-tint: #eaf3f7;
  --text: #162b3d;
  --text-soft: #2b465d;
  --muted: #5d758a;
  --border: #233e54;
  --paper-border: #1a3246;

  /* 核心蓝色与青色 */
  --primary-blue: #1c62d6;
  --primary-blue-dark: #1248a3;
  --accent-cyan: #0aa3a8;
  --accent-cyan-light: #ddf6f6;
  --accent-cyan-hover: #088b90;
  --highlight-blue-soft: #e3effd;

  /* 笔触与几何度 */
  --ink-stroke: 2.2px;
  --hand-radius: 255px 15px 225px 15px/15px 225px 15px 255px;
  --hand-radius-sm: 180px 10px 160px 12px/12px 170px 10px 160px;
  --shadow-offset: 3px 4px 0px rgba(22, 43, 61, 0.85);
  --shadow-blue: 3px 4px 0px rgba(28, 98, 214, 0.85);

  /* 字阶规范 */
  --fs-hero: 52px;
  --fs-h1: 42px;
  --fs-h2: 24px;
  --fs-lead: 20px;
  --fs-body: 17px;
  --fs-label: 14px;
  --fs-tick: 12px;

  /* 字体族 */
  --font-display: "NTF-caveat", "NTF-lxgw-wenkai", cursive, sans-serif;
  --font-sans: "NTF-inter", "NTF-lxgw-wenkai", -apple-system, BlinkMacSystemFont, sans-serif;
  --font-num: "NTF-inter", "NTF-caveat", monospace, sans-serif;
}

#stage {
  background-color: var(--bg);
  background-image: 
    radial-gradient(circle at 50% 0%, rgba(10, 163, 168, 0.08) 0%, transparent 60%),
    radial-gradient(circle at 100% 100%, rgba(28, 98, 214, 0.06) 0%, transparent 50%),
    linear-gradient(to right, rgba(35, 62, 84, 0.04) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(35, 62, 84, 0.04) 1px, transparent 1px);
  background-size: 100% 100%, 100% 100%, 32px 32px, 32px 32px;
  background-position: 0 0, 0 0, -1px -1px, -1px -1px;
  color: var(--text);
  font-family: var(--font-sans);
  overflow: hidden;
  box-sizing: border-box;
}

/* ================= 标题与排版 ================= */
.nt-hero {
  font-family: var(--font-display);
  font-size: var(--fs-hero);
  line-height: 1.15;
  font-weight: 700;
  color: var(--text);
  margin: 0;
  letter-spacing: -0.01em;
}

.nt-hero:lang(zh) {
  font-family: "NTF-lxgw-wenkai", cursive, sans-serif;
  font-weight: 500;
}

.nt-title {
  font-family: var(--font-display);
  font-size: var(--fs-h1);
  line-height: 1.25;
  font-weight: 700;
  color: var(--text);
  margin: 0;
}

.nt-title:lang(zh) {
  font-family: "NTF-lxgw-wenkai", cursive, sans-serif;
  font-weight: 500;
}

.nt-subtitle {
  font-family: "NTF-lxgw-wenkai", var(--font-sans);
  font-size: var(--fs-h2);
  line-height: 1.35;
  font-weight: 500;
  color: var(--primary-blue-dark);
  margin: 0;
}

.nt-lead {
  font-family: var(--font-sans);
  font-size: var(--fs-lead);
  line-height: 1.5;
  color: var(--text-soft);
}

.nt-body {
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.6;
  color: var(--text-soft);
}

.nt-label {
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  line-height: 1.4;
  color: var(--muted);
}

.nt-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 12px;
  background-color: var(--highlight-blue-soft);
  border: 1.8px solid var(--primary-blue);
  border-radius: var(--hand-radius-sm);
  color: var(--primary-blue);
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 600;
}

.nt-tag-cyan {
  background-color: var(--accent-cyan-light);
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
}

/* ================= 手绘框体与板块 ================= */
.nt-hand-box {
  background-color: #ffffff;
  border: var(--ink-stroke) solid var(--paper-border);
  border-radius: var(--hand-radius);
  box-shadow: var(--shadow-offset);
  position: relative;
  box-sizing: border-box;
}

.nt-hand-box-blue {
  border-color: var(--primary-blue);
  box-shadow: var(--shadow-blue);
  background-color: #ffffff;
}

.nt-hand-box-soft {
  background-color: var(--bg-tint);
  border: var(--ink-stroke) dashed var(--muted);
  border-radius: var(--hand-radius);
  box-shadow: none;
}

/* 手绘图钉/胶带小装饰类 */
.nt-tape-decor {
  position: absolute;
  top: -10px;
  left: 36px;
  width: 70px;
  height: 20px;
  background-color: rgba(14, 165, 168, 0.22);
  border: 1px dashed rgba(14, 165, 168, 0.45);
  transform: rotate(-3deg);
  pointer-events: none;
}

/* ================= 控件与交互 ================= */
.nt-hand-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 22px;
  background-color: var(--primary-blue);
  color: #ffffff;
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 600;
  border: var(--ink-stroke) solid var(--paper-border);
  border-radius: var(--hand-radius-sm);
  box-shadow: 2.5px 3px 0px var(--paper-border);
  cursor: pointer;
  user-select: none;
  transition: transform 0.12s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.12s ease;
}

.nt-hand-btn:lang(zh) {
  font-family: "NTF-lxgw-wenkai", sans-serif;
}

.nt-hand-btn:hover {
  transform: translate(-1px, -1px);
  box-shadow: 3.5px 4.5px 0px var(--paper-border);
  background-color: #276de0;
}

.nt-hand-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 0.5px 1px 0px var(--paper-border);
}

.nt-hand-btn-cyan {
  background-color: var(--accent-cyan);
}

.nt-hand-btn-cyan:hover {
  background-color: var(--accent-cyan-hover);
}

.nt-hand-btn-outline {
  background-color: #ffffff;
  color: var(--text);
}

.nt-hand-btn-outline:hover {
  background-color: var(--bg-tint);
}

/* 滑块样式：手绘槽与圆旋钮 */
.nt-slider-wrapper {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.nt-slider-label {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: var(--fs-label);
  font-weight: 600;
  color: var(--text);
}

.nt-slider-val {
  font-family: var(--font-num);
  font-size: 22px;
  font-weight: 700;
  color: var(--primary-blue);
}

.nt-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 12px;
  background: var(--bg-tint);
  border: 2px solid var(--paper-border);
  border-radius: 999px;
  outline: none;
  cursor: pointer;
}

.nt-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 28px;
  height: 28px;
  background: var(--accent-cyan);
  border: 2.2px solid var(--paper-border);
  border-radius: 50% 48% 52% 49% / 49% 52% 48% 51%;
  box-shadow: 2px 2px 0px var(--paper-border);
  cursor: grab;
  transition: transform 0.1s ease, background-color 0.1s ease;
}

.nt-slider::-webkit-slider-thumb:hover {
  transform: scale(1.12);
  background: #11b3b8;
}

.nt-slider::-webkit-slider-thumb:active {
  cursor: grabbing;
  transform: scale(0.98);
}

.nt-slider::-moz-range-thumb {
  width: 28px;
  height: 28px;
  background: var(--accent-cyan);
  border: 2.2px solid var(--paper-border);
  border-radius: 50%;
  box-shadow: 2px 2px 0px var(--paper-border);
  cursor: grab;
}

/* ================= 图表与曲线视觉 ================= */
.nt-chart {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.nt-grid-line {
  stroke: rgba(35, 62, 84, 0.2);
  stroke-width: 1.6px;
  stroke-dasharray: 4 5;
  stroke-linecap: round;
}

.nt-axis-line {
  stroke: var(--paper-border);
  stroke-width: 2.4px;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.nt-curve {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: d 0.25s ease, stroke 0.2s ease;
}

.nt-curve-blue {
  stroke: var(--primary-blue);
  stroke-width: 4.5px;
}

.nt-curve-cyan {
  stroke: var(--accent-cyan);
  stroke-width: 4px;
}

.nt-curve-fill {
  opacity: 0.16;
}

.nt-node {
  stroke: var(--paper-border);
  stroke-width: 2.2px;
  transition: cx 0.25s ease, cy 0.25s ease;
}

.nt-node-blue {
  fill: var(--primary-blue);
}

.nt-node-cyan {
  fill: var(--accent-cyan);
}

.nt-node-white {
  fill: #ffffff;
}

.nt-chart-text {
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  fill: var(--text);
  font-weight: 600;
}

.nt-chart-text-muted {
  font-family: var(--font-sans);
  font-size: var(--fs-tick);
  fill: var(--muted);
}

.nt-highlight-card {
  padding: 16px 20px;
  background: #ffffff;
  border: 2.2px solid var(--primary-blue);
  border-radius: var(--hand-radius-sm);
  box-shadow: 3px 4px 0px var(--primary-blue);
}

.nt-highlight-card .nt-val-display {
  font-family: var(--font-num);
  font-size: 38px;
  font-weight: 700;
  color: var(--primary-blue);
  line-height: 1.1;
}

/* ================= 辅助细节 ================= */
.nt-callout-doodle {
  position: relative;
  display: inline-block;
}

.nt-callout-doodle::after {
  content: "";
  position: absolute;
  left: -2px;
  right: -2px;
  bottom: 2px;
  height: 8px;
  background-color: rgba(14, 165, 168, 0.25);
  border-radius: 4px;
  z-index: -1;
  transform: rotate(-0.5deg);
}
